<?php
/** Central payment ledger. Manual proofs remain an audit-only view. */
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/functions.php';
require_once __DIR__ . '/../includes/branch_context.php';
require_once __DIR__ . '/../includes/branch_ui.php';
require_once __DIR__ . '/../includes/provider_payments.php';
require_once __DIR__ . '/../includes/payment_verification.php';
require_role(['Admin', 'Manager']);
if (!isset($base_path)) { if (file_exists(__DIR__ . '/../config.php')) require_once __DIR__ . '/../config.php'; $base_path = defined('BASE_PATH') ? BASE_PATH : '/printflow'; }
$current_user = get_logged_in_user(); $isManagerPanel = defined('MANAGER_PANEL') && MANAGER_PANEL;
$branchCtx = init_branch_context(false); $branchId = $branchCtx['selected_branch_id'];
$search = trim((string)($_GET['search'] ?? '')); $period = strtolower(trim((string)($_GET['period'] ?? 'today')));
$methodFilter = strtolower(trim((string)($_GET['method'] ?? 'all'))); $sourceFilter = strtolower(trim((string)($_GET['source'] ?? 'all')));
$statusFilter = strtolower(trim((string)($_GET['status'] ?? 'all'))); $legacy = (string)($_GET['view'] ?? '') === 'legacy';
$from = trim((string)($_GET['from'] ?? '')); $to = trim((string)($_GET['to'] ?? '')); $page = max(1, (int)($_GET['page'] ?? 1)); $perPage = 25;
if (!in_array($period, ['today','week','month','custom','all'], true)) $period = 'today';
if (!in_array($methodFilter, ['all','cash','qrph'], true)) $methodFilter = 'all'; if (!in_array($sourceFilter, ['all','online','pos'], true)) $sourceFilter = 'all';
if (!in_array($statusFilter, ['all','paid','processing','expired','failed'], true)) $statusFilter = 'all';
function pf_payment_status_label(string $s): string { return match(strtolower($s)) { 'paid'=>'Paid','awaiting_payment','generating'=>'Processing','expired'=>'Expired','failed','cancelled'=>'Failed',default=>ucfirst($s ?: 'Processing')}; }
function pf_payment_badge(string $s): string { $c=['Paid'=>['#dcfce7','#166534'],'Processing'=>['#fef3c7','#92400e'],'Expired'=>['#fee2e2','#991b1b'],'Failed'=>['#fee2e2','#991b1b']]; [$b,$f]=$c[$s]??['#f3f4f6','#4b5563']; return '<span class="badge" style="background:'.$b.';color:'.$f.'">'.htmlspecialchars($s).'</span>'; }
function pf_payment_range(string $p,string $f,string $t): array { if($p==='all')return ['','']; if($p==='custom')return [$f!==''?$f.' 00:00:00':'',$t!==''?$t.' 23:59:59':'']; if($p==='week')return [date('Y-m-d 00:00:00',strtotime('monday this week')),date('Y-m-d 23:59:59')]; if($p==='month')return [date('Y-m-01 00:00:00'),date('Y-m-d 23:59:59')]; return [date('Y-m-d 00:00:00'),date('Y-m-d 23:59:59')]; }
[$rangeStart,$rangeEnd]=pf_payment_range($period,$from,$to); $transactions=[];
if (printflow_provider_payments_ready()) {
    // Canonical QR Ph ledger. Schema makes provider_payment_id unique, preventing duplicate provider rows.
    $paidAmount=db_table_has_column('provider_payments','paid_amount_centavos')?'COALESCE(pp.paid_amount_centavos, pp.amount_centavos)':'pp.amount_centavos';
    $paidAt=db_table_has_column('provider_payments','provider_paid_at')?'COALESCE(pp.provider_paid_at, pp.paid_at, pp.created_at)':'COALESCE(pp.paid_at, pp.created_at)';
    $sql="SELECT pp.id,pp.order_id,pp.channel,pp.status,pp.provider_payment_id,{$paidAmount} AS paid_amount,{$paidAt} AS occurred_at,o.reference_id,CONCAT_WS(' ',c.first_name,c.last_name) customer_name,b.branch_name FROM provider_payments pp LEFT JOIN orders o ON o.order_id=pp.order_id LEFT JOIN customers c ON c.customer_id=pp.customer_id LEFT JOIN branches b ON b.id=COALESCE(NULLIF(pp.branch_id,0),o.branch_id) WHERE 1=1";
    $types='';$params=[]; if(printflow_branch_value_is_all($branchId))$sql.=" AND COALESCE(NULLIF(pp.branch_id,0),o.branch_id) IN (SELECT id FROM branches WHERE status != 'Archived')";else{$sql.=' AND COALESCE(NULLIF(pp.branch_id,0),o.branch_id)=?';$types.='i';$params[]=(int)$branchId;}
    if($rangeStart!==''){$sql.=" AND {$paidAt}>=?";$types.='s';$params[]=$rangeStart;} if($rangeEnd!==''){$sql.=" AND {$paidAt}<=?";$types.='s';$params[]=$rangeEnd;}
    if($sourceFilter!=='all'){$sql.=' AND pp.channel=?';$types.='s';$params[]=$sourceFilter;} if($statusFilter!=='all'){if($statusFilter==='processing')$sql.=" AND pp.status IN ('generating','awaiting_payment')";elseif($statusFilter==='failed')$sql.=" AND pp.status IN ('failed','cancelled')";else{$sql.=' AND pp.status=?';$types.='s';$params[]=$statusFilter;}}
    if($search!==''){$l='%'.$search.'%';$sql.=" AND (pp.provider_payment_id LIKE ? OR o.reference_id LIKE ? OR CONCAT_WS(' ',c.first_name,c.last_name) LIKE ? OR CAST(pp.order_id AS CHAR) LIKE ?)";$types.='ssss';array_push($params,$l,$l,$l,$l);}
    foreach(db_query($sql." ORDER BY {$paidAt} DESC,pp.id DESC",$types?:null,$params?:null)?:[] as $r)$transactions[]=['order_id'=>(int)$r['order_id'],'reference'=>(string)($r['provider_payment_id']?:'Ledger #'.$r['id']),'order'=>(string)($r['reference_id']?:'Order #'.$r['order_id']),'customer'=>trim((string)$r['customer_name'])?:'Walk-in Guest','source'=>strtolower((string)$r['channel'])==='pos'?'POS':'Online','amount'=>(float)$r['paid_amount']/100,'method'=>'QR Ph','status'=>pf_payment_status_label((string)$r['status']),'at'=>(string)$r['occurred_at'],'branch'=>(string)($r['branch_name']??'Unassigned')];
}
// Cash is intentionally read from completed POS orders: it has no PayMongo provider reference.
$sql="SELECT o.order_id,o.reference_id,o.total_amount,o.order_date,CONCAT_WS(' ',c.first_name,c.last_name) customer_name,b.branch_name FROM orders o LEFT JOIN customers c ON c.customer_id=o.customer_id LEFT JOIN branches b ON b.id=o.branch_id WHERE LOWER(TRIM(COALESCE(o.order_source,''))) IN ('pos','pos_merged') AND LOWER(TRIM(COALESCE(o.payment_method,'')))='cash' AND LOWER(TRIM(o.payment_status))='paid'";
$types='';$params=[];if(printflow_branch_value_is_all($branchId))$sql.=" AND o.branch_id IN (SELECT id FROM branches WHERE status != 'Archived')";else{$sql.=' AND o.branch_id=?';$types.='i';$params[]=(int)$branchId;}if($rangeStart!==''){$sql.=' AND o.order_date>=?';$types.='s';$params[]=$rangeStart;}if($rangeEnd!==''){$sql.=' AND o.order_date<=?';$types.='s';$params[]=$rangeEnd;}if($sourceFilter==='online'||$methodFilter==='qrph'||($statusFilter!=='all'&&$statusFilter!=='paid'))$sql.=' AND 1=0';if($search!==''){$l='%'.$search.'%';$sql.=" AND (o.reference_id LIKE ? OR CAST(o.order_id AS CHAR) LIKE ? OR CONCAT_WS(' ',c.first_name,c.last_name) LIKE ?)";$types.='sss';array_push($params,$l,$l,$l);}
foreach(db_query($sql.' ORDER BY o.order_date DESC,o.order_id DESC',$types?:null,$params?:null)?:[] as $r)$transactions[]=['order_id'=>(int)$r['order_id'],'reference'=>'POS-'.str_pad((string)$r['order_id'],6,'0',STR_PAD_LEFT),'order'=>(string)($r['reference_id']?:'Order #'.$r['order_id']),'customer'=>trim((string)$r['customer_name'])?:'Walk-in Guest','source'=>'POS','amount'=>(float)$r['total_amount'],'method'=>'Cash','status'=>'Paid','at'=>(string)$r['order_date'],'branch'=>(string)($r['branch_name']??'Unassigned')];
if($methodFilter==='cash')$transactions=array_values(array_filter($transactions,fn($r)=>$r['method']==='Cash'));if($methodFilter==='qrph')$transactions=array_values(array_filter($transactions,fn($r)=>$r['method']==='QR Ph'));usort($transactions,fn($a,$b)=>strtotime($b['at'])<=>strtotime($a['at']));
$paid=array_values(array_filter($transactions,fn($r)=>$r['status']==='Paid'));$totalSales=array_sum(array_column($paid,'amount'));$cashSales=array_sum(array_column(array_filter($paid,fn($r)=>$r['method']==='Cash'),'amount'));$qrSales=array_sum(array_column(array_filter($paid,fn($r)=>$r['method']==='QR Ph'),'amount'));$totalPages=max(1,(int)ceil(count($transactions)/$perPage));$page=min($page,$totalPages);$visible=array_slice($transactions,($page-1)*$perPage,$perPage);
$legacyProofs=[];if($legacy&&payment_verification_ensure_schema())$legacyProofs=db_query("SELECT ps.id,ps.order_id,ps.verification_status,ps.expected_amount,ps.created_at,ps.receipt_file,CONCAT_WS(' ',c.first_name,c.last_name) customer_name FROM payment_submissions ps LEFT JOIN customers c ON c.customer_id=ps.customer_id WHERE ps.receipt_file IS NOT NULL AND ps.receipt_file<>'' ORDER BY ps.created_at DESC LIMIT 100")?:[];
$query=static function(array $o=[]){$q=array_merge($_GET,$o);foreach($q as $k=>$v)if($v===''||$v===null)unset($q[$k]);return '?'.http_build_query($q);};$page_title=$isManagerPanel?'Payments - Manager | PrintFlow':'Payments - Admin | PrintFlow';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($page_title)?></title><link rel="stylesheet" href="<?=htmlspecialchars($base_path)?>/public/assets/css/output.css"><?php include __DIR__ . '/../includes/admin_style.php';render_branch_css();?><style>.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:20px 0}.kpi,.card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:17px}.label,th{font-size:11px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.05em}.value{font-size:25px;font-weight:800;margin-top:6px}.sub{font-size:12px;color:#6b7280}.filters,.tabs{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:18px}.filters select,.filters input{height:38px;border:1px solid #d1d5db;border-radius:7px;padding:0 10px;background:#fff}.tab{padding:8px 12px;border-radius:7px;text-decoration:none;border:1px solid #d1d5db;color:#374151}.tab.active{background:#0f766e;color:#fff;border-color:#0f766e}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px 8px;border-bottom:1px solid #eef0f2;white-space:nowrap;text-align:left}.badge{display:inline-flex;border-radius:999px;padding:3px 9px;font-size:12px;font-weight:600}@media(max-width:800px){.kpis{grid-template-columns:repeat(2,1fr)}}</style></head><body><?php include __DIR__.'/../includes/'.(($current_user['role']??'')==='Admin'?'admin_sidebar.php':'manager_sidebar.php');?><div class="main-content"><header class="pf-mobile-branch-inline"><h1 class="page-title">Payments</h1><?php if(!$isManagerPanel)render_branch_selector($branchCtx);?></header><main><?php render_branch_context_banner($branchCtx['branch_name']);?><div class="tabs"><a class="tab <?=!$legacy?'active':''?>" href="<?=htmlspecialchars($query(['view'=>'','page'=>1]))?>">Transactions</a><a class="tab <?=$legacy?'active':''?>" href="<?=htmlspecialchars($query(['view'=>'legacy','page'=>1]))?>">Legacy proofs</a></div><?php if(!$legacy):?><div class="kpis"><div class="kpi"><div class="label">Total Sales</div><div class="value"><?=format_currency($totalSales)?></div><div class="sub">Paid transactions only</div></div><div class="kpi"><div class="label">Cash</div><div class="value"><?=format_currency($cashSales)?></div><div class="sub">Successful POS cash</div></div><div class="kpi"><div class="label">QR Ph</div><div class="value"><?=format_currency($qrSales)?></div><div class="sub">Online + POS</div></div><div class="kpi"><div class="label">Total Transactions</div><div class="value"><?=number_format(count($paid))?></div><div class="sub">Paid in selected period</div></div></div><form class="filters" method="get"><input type="hidden" name="branch_id" value="<?=printflow_branch_value_is_all($branchId)?'all':(int)$branchId?>"><input name="search" placeholder="Search reference, order, customer" value="<?=htmlspecialchars($search)?>"><select name="period"><option value="today" <?=$period==='today'?'selected':''?>>Today</option><option value="week" <?=$period==='week'?'selected':''?>>This Week</option><option value="month" <?=$period==='month'?'selected':''?>>This Month</option><option value="all" <?=$period==='all'?'selected':''?>>All Time</option><option value="custom" <?=$period==='custom'?'selected':''?>>Custom Range</option></select><input type="date" name="from" value="<?=htmlspecialchars($from)?>"><input type="date" name="to" value="<?=htmlspecialchars($to)?>"><select name="method"><option value="all">All Methods</option><option value="cash" <?=$methodFilter==='cash'?'selected':''?>>Cash</option><option value="qrph" <?=$methodFilter==='qrph'?'selected':''?>>QR Ph</option></select><select name="source"><option value="all">All Sources</option><option value="online" <?=$sourceFilter==='online'?'selected':''?>>Online</option><option value="pos" <?=$sourceFilter==='pos'?'selected':''?>>POS</option></select><select name="status"><option value="all">All Statuses</option><option value="paid" <?=$statusFilter==='paid'?'selected':''?>>Paid</option><option value="processing" <?=$statusFilter==='processing'?'selected':''?>>Processing</option><option value="expired" <?=$statusFilter==='expired'?'selected':''?>>Expired</option><option value="failed" <?=$statusFilter==='failed'?'selected':''?>>Failed</option></select><button class="btn-action blue" type="submit">Apply</button></form><div class="card table-wrap"><table><thead><tr><th>Reference</th><th>Order / Receipt</th><th>Customer</th><th>Source</th><th>Amount</th><th>Method</th><th>Status</th><th>Date / Time</th><th>Action</th></tr></thead><tbody><?php if(!$visible):?><tr><td colspan="9" class="sub">No payment transactions found.</td></tr><?php endif;foreach($visible as $tx):$url=$base_path.($isManagerPanel?'/manager/orders.php?search=':'/admin/orders_management.php?search=').urlencode((string)$tx['order_id']);?><tr><td><?=htmlspecialchars($tx['reference'])?></td><td><?=htmlspecialchars($tx['order'])?><div class="sub"><?=htmlspecialchars($tx['branch'])?></div></td><td><?=htmlspecialchars($tx['customer'])?></td><td><?=htmlspecialchars($tx['source'])?></td><td><?=format_currency($tx['amount'])?></td><td><?=htmlspecialchars($tx['method'])?></td><td><?=pf_payment_badge($tx['status'])?></td><td><?=htmlspecialchars(date('M j, Y g:i A',strtotime($tx['at'])))?></td><td><a class="btn-action blue" href="<?=htmlspecialchars($url)?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php if($totalPages>1)echo render_pagination($page,$totalPages,array_filter(array_merge($_GET,['page'=>null])));?><?php else:?><div class="card table-wrap"><h3 style="margin:0 0 12px">Manual proof history</h3><p class="sub">Historical screenshots and review statuses only; excluded from sales totals.</p><table><thead><tr><th>Proof</th><th>Order</th><th>Customer</th><th>Amount</th><th>Review Status</th><th>Uploaded</th></tr></thead><tbody><?php if(!$legacyProofs):?><tr><td colspan="6" class="sub">No legacy proofs found.</td></tr><?php endif;foreach($legacyProofs as $r):?><tr><td>#<?=(int)$r['id']?></td><td>Order #<?=(int)$r['order_id']?></td><td><?=htmlspecialchars(trim((string)$r['customer_name'])?:'Customer')?></td><td><?=format_currency((float)$r['expected_amount'])?></td><td><?=htmlspecialchars((string)$r['verification_status'])?></td><td><?=htmlspecialchars(date('M j, Y g:i A',strtotime((string)$r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></main></div></body></html>
